package main

import (
	"context"
	"os"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
)

func main() {
	var c *dynamodb.Client
	c.GetItem(context.Background(), &dynamodb.GetItemInput{TableName: aws.String(getEnv("TABLE", defaultTable))})
	c.GetItem(context.Background(), &dynamodb.GetItemInput{TableName: aws.String(os.Getenv("T2") + "-y")})
}

